package main

import (
	"io/ioutil"
	"net/url"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/go-test/deep"
)

func parseURL(t testing.TB, s string) *url.URL {
	url, err := url.Parse(s)
	if err != nil {
		t.Fatal(err)
	}
	return url
}

func ptrTime(v time.Time) *time.Time {
	return &v
}

func TestReadFile(t *testing.T) {
	var tests = []struct {
		Data string
		Entry
	}{
		{
			"Bugfix: subject line\n\nhttps://github.com/restic/restic/issues/12345",
			Entry{
				Title:      "Subject line",
				Type:       "Bugfix",
				TypeShort:  "Fix",
				PrimaryID:  12345,
				PrimaryURL: parseURL(t, "https://github.com/restic/restic/issues/12345"),
				URLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
				},
				Issues: []string{"12345"},
				IssueURLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
				},
			},
		},
		{
			`Security: short and terse summary

A block of text. Lorem ipsum or so. May
wrap around,
arbitrarily.

second block of text.
may also contain
many different lines.

Last block contains just
a few
links.

https://github.com/restic/restic/issues/12345
https://github.com/restic/restic/pull/666666
`,
			Entry{
				Title:     "Short and terse summary",
				Type:      "Security",
				TypeShort: "Sec",
				Paragraphs: []string{
					"A block of text. Lorem ipsum or so. May wrap around, arbitrarily.",
					"Second block of text. may also contain many different lines.",
					"Last block contains just a few links.",
				},
				URLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
					parseURL(t, "https://github.com/restic/restic/pull/666666"),
				},
				PrimaryID:  12345,
				PrimaryURL: parseURL(t, "https://github.com/restic/restic/issues/12345"),
				Issues:     []string{"12345"},
				IssueURLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
				},
				PRs: []string{"666666"},
				PRURLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/pull/666666"),
				},
			},
		},
		{
			`Enhancement: foo bar subject

` + "```bash\necho 'test code block with type'\n```" + `

https://github.com/restic/restic/issues/12345
https://github.com/restic/rest-server/issues/232323
https://github.com/restic/restic/pull/666666
https://forum.restic.net/t/getting-last-successful-backup-time/531
`,
			Entry{
				Title:      "Foo bar subject",
				Paragraphs: []string{"```bash\necho 'test code block with type'\n```"},
				Type:       "Enhancement",
				TypeShort:  "Enh",
				PrimaryID:  12345,
				PrimaryURL: parseURL(t, "https://github.com/restic/restic/issues/12345"),
				Issues:     []string{"12345", "232323"},
				IssueURLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
					parseURL(t, "https://github.com/restic/rest-server/issues/232323"),
				},
				PRs: []string{"666666"},
				PRURLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/pull/666666"),
				},
				URLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
					parseURL(t, "https://github.com/restic/rest-server/issues/232323"),
					parseURL(t, "https://github.com/restic/restic/pull/666666"),
					parseURL(t, "https://forum.restic.net/t/getting-last-successful-backup-time/531"),
				},
				OtherURLs: []*url.URL{
					parseURL(t, "https://forum.restic.net/t/getting-last-successful-backup-time/531"),
				},
			},
		},
		{
			"Security: short and terse summary\n\n```\nexample\n   with\n       random spaces\n```\n\nLast block contains just\na few\nlinks.\n\nhttps://github.com/restic/restic/issues/12345",
			Entry{
				Title:     "Short and terse summary",
				Type:      "Security",
				TypeShort: "Sec",
				Paragraphs: []string{
					"```\nexample\n   with\n       random spaces\n```",
					"Last block contains just a few links.",
				},
				URLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
				},
				PrimaryID:  12345,
				PrimaryURL: parseURL(t, "https://github.com/restic/restic/issues/12345"),
				Issues:     []string{"12345"},
				IssueURLs: []*url.URL{
					parseURL(t, "https://github.com/restic/restic/issues/12345"),
				},
			},
		},
	}

	for _, test := range tests {
		t.Run("", func(t *testing.T) {
			f, err := ioutil.TempFile("", "calens-test-")
			if err != nil {
				t.Fatal(err)
			}

			defer os.Remove(f.Name())

			_, err = f.Write([]byte(test.Data))
			if err != nil {
				t.Fatal(err)
			}

			err = f.Close()
			if err != nil {
				t.Fatal(err)
			}

			entry := readFile(f.Name())
			if diff := deep.Equal(test.Entry, entry); diff != nil {
				t.Error(diff)
			}
		})
	}
}
func TestReadReleases(t *testing.T) {
	type testData struct {
		Date       *time.Time
		FolderName string
		Version    string
	}
	dir := t.TempDir()
	releases := []testData{
		{Date: nil, FolderName: "unreleased", Version: "unreleased"},
		{Date: ptrTime(time.Date(2023, time.November, 12, 0, 0, 0, 0, time.UTC)), FolderName: "2.0.0-rc.1+build.12345_2023-11-12", Version: "2.0.0-rc.1+build.12345"},
		{Date: ptrTime(time.Date(2023, time.November, 10, 0, 0, 0, 0, time.UTC)), FolderName: "0.0.1-rc.1_2023-11-10", Version: "0.0.1-rc.1"},
		{Date: ptrTime(time.Date(2023, time.November, 10, 0, 0, 0, 0, time.UTC)), FolderName: "1.0.1_2023-11-10", Version: "1.0.1"},
		{Date: ptrTime(time.Date(2023, time.November, 9, 0, 0, 0, 0, time.UTC)), FolderName: "4.0.0_2023-11-09", Version: "4.0.0"},
		{Date: ptrTime(time.Date(2023, time.November, 8, 0, 0, 0, 0, time.UTC)), FolderName: "1.0.2-alpha.10_2023-11-08", Version: "1.0.2-alpha.10"},
		{Date: ptrTime(time.Date(2023, time.September, 7, 0, 0, 0, 0, time.UTC)), FolderName: "1.0.0_2023-09-07", Version: "1.0.0"},
		{Date: ptrTime(time.Date(2023, time.May, 1, 0, 0, 0, 0, time.UTC)), FolderName: "12.10.21_2023-05-01", Version: "12.10.21"},
	}
	for _, release := range releases {
		err := os.Mkdir(filepath.Join(dir, release.FolderName), 0750)
		if err != nil {
			t.Fatal(err)
		}
	}
	parsedReleases := readReleases(dir)
	// test the sorting and the parsing of the folder names
	for i, parsedRelease := range parsedReleases {
		if ((releases[i].Date == nil || parsedRelease.Date == nil) && releases[i].Date != parsedRelease.Date) || (releases[i].Date != nil && !releases[i].Date.Equal(*parsedRelease.Date)) {
			t.Fatalf("date mismatch, expected %v, got %v", releases[i].Date, parsedRelease.Date)
		}
		if releases[i].Version != parsedRelease.Version {
			t.Fatalf("version mismatch, expected %v, got %v", releases[i].Version, parsedRelease.Version)
		}
	}
}

func TestWrapIndent(t *testing.T) {
	var tests = []struct {
		In     string
		Width  int
		Indent int
		Out    string
	}{
		{"Example string", 80, 4, "Example string"},
		{"Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.", 70, 3, "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do\n   eiusmod tempor incididunt ut labore et dolore magna aliqua."},
		{"Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.", 55, 2, "Lorem ipsum dolor sit amet, consectetur adipiscing\n  elit, sed do eiusmod tempor incididunt ut labore et\n  dolore magna aliqua."},
		{"```\nexample\n   with\n       random spaces\n```", 10, 3, "```\n   example\n      with\n          random spaces\n   ```"},
	}

	for _, test := range tests {
		t.Run("", func(t *testing.T) {
			res, err := wrapIndent(test.In, test.Width, test.Indent)
			if err != nil {
				t.Fatal(err)
			}

			if diff := deep.Equal(res, test.Out); diff != nil {
				t.Error(diff)
			}
		})
	}
}

package main

import (
	"bufio"
	"errors"
	"fmt"
	"io/ioutil"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"text/template"

	"github.com/Masterminds/semver/v3"
	"github.com/Masterminds/sprig/v3"
	"github.com/spf13/pflag"
)

var opts struct {
	Output       string
	InputDir     string
	TemplateFile string
	Versions     []string
}

func init() {
	pflag.StringVarP(&opts.InputDir, "input", "i", "changelog", "read input files from `dir`")
	pflag.StringVarP(&opts.Output, "output", "o", "", "write generated changelog to this `file` (default: print to stdout)")
	pflag.StringVarP(&opts.TemplateFile, "template", "t", filepath.FromSlash("changelog/CHANGELOG.tmpl"), "read template from `file`")
	pflag.StringSliceVar(&opts.Versions, "version", nil, "only print `version` (separate multiple versions with commas)")
	pflag.Parse()
}

func die(msg string, args ...interface{}) {
	if !strings.HasSuffix(msg, "\\n") {
		msg += "\n"
	}
	fmt.Fprintf(os.Stderr, msg, args...)
	os.Exit(1)
}

// files lists all file names in dir. The file name is split by _, and the first component is used as the key in the resulting map.
func files(dir string) []string {
	d, err := os.Open(dir)
	if err != nil {
		die("error opening dir: %v", err)
	}

	names, err := d.Readdirnames(-1)
	if err != nil {
		_ = d.Close()
		die("error listing dir: %v", err)
	}

	err = d.Close()
	if err != nil {
		die("error closing dir: %v", err)
	}

	sort.Strings(names)

	var files []string
	for _, name := range names {
		// skip the template and versions file
		if name == "TEMPLATE" || name == "releases" {
			continue
		}

		// skip dot files
		if strings.HasPrefix(name, ".") {
			continue
		}

		files = append(files, filepath.Join(dir, name))
	}

	return files
}

// Release is one release, with an optional release date.
type Release struct {
	path    string
	Version string
	Date    *time.Time
}

// ReleaseSlice allows sorting a slice of releases by the release date
// with Go < 1.8
type ReleaseSlice []Release

// Len is the number of elements in the collection.
func (s ReleaseSlice) Len() int {
	return len(s)
}

// Less reports whether the element with
// index i should sort before the element with index j.
func (s ReleaseSlice) Less(i, j int) bool {
	if s[i].Date == nil {
		return true
	}

	if s[j].Date == nil {
		return false
	}

	return s[j].Date.Before(*s[i].Date)
}

// Swap swaps the elements with indexes i and j.
func (s ReleaseSlice) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}

var versionRegex = regexp.MustCompile(`^([^_]+)(?:_(\d{4}-\d{2}-\d{2}))?$`)

// readReleases lists the directory and parses all releases from the subdir
// names there. A valid release subdir has the format "x.y.z_YYYY-MM-DD", the
// underscore and date is optional (for unreleased versions). The resulting
// slice is sorted by the release dates, starting with unreleased versions and
// continuing with the other versions, newest first.
func readReleases(dir string) (result []Release) {
	f, err := os.Open(dir)
	if err != nil {
		die("unable to open dir: %v", err)
	}

	entries, err := f.Readdir(-1)
	if err != nil {
		die("unable to list directory: %v", err)
	}

	err = f.Close()
	if err != nil {
		die("close dir: %v", err)
	}

	for _, entry := range entries {
		if !entry.Mode().IsDir() {
			continue
		}

		if entry.Name() == "unreleased" {
			rel := Release{
				path:    filepath.Join(dir, entry.Name()),
				Version: "unreleased",
			}
			result = append(result, rel)
			continue
		}

		data := versionRegex.FindStringSubmatch(entry.Name())
		if len(data) == 0 {
			die("invalid subdir name %v", filepath.Join(dir, entry.Name()))
			continue
		}

		ver, err := semver.NewVersion(data[1])
		if err != nil {
			die("invalid subdir name %v. Parsing semver returned error: %v", filepath.Join(dir, entry.Name()), err)
		}
		date := data[2]

		rel := Release{
			path:    filepath.Join(dir, entry.Name()),
			Version: ver.String(),
		}

		if date != "" {
			t, err := time.Parse("2006-01-02", date)
			if err != nil {
				die("unable to parse date %q: %v", date, err)
			}
			rel.Date = &t
		}

		result = append(result, rel)
	}

	sort.Sort(ReleaseSlice(result))

	return result
}

// Entry describes a change.
type Entry struct {
	Type       string
	TypeShort  string
	Title      string
	Paragraphs []string
	URLs       []*url.URL
	Issues     []string
	IssueURLs  []*url.URL
	PRs        []string
	PRURLs     []*url.URL
	OtherURLs  []*url.URL
	PrimaryID  int64
	PrimaryURL *url.URL
}

// EntryTypePriority contains the list of valid types, order is priority in the changelog.
var EntryTypePriority = map[string]int{
	"Security":    1,
	"Bugfix":      2,
	"Change":      3,
	"Enhancement": 4,
}

// EntryTypeAbbreviation contains the shortened entry types for the overview.
var EntryTypeAbbreviation = map[string]string{
	"Security":    "Sec",
	"Bugfix":      "Fix",
	"Change":      "Chg",
	"Enhancement": "Enh",
}

// EntrySlice allows sorting a slice of releases by the priority of the entry
// (as defined in EntryTypePriority) with Go < 1.8
type EntrySlice []Entry

// Len is the number of elements in the collection.
func (s EntrySlice) Len() int {
	return len(s)
}

// Less reports whether the element with
// index i should sort before the element with index j.
func (s EntrySlice) Less(i, j int) bool {
	if s[i].Type == s[j].Type {
		return s[i].PrimaryID < s[j].PrimaryID
	}
	return EntryTypePriority[s[i].Type] < EntryTypePriority[s[j].Type]
}

// Swap swaps the elements with indexes i and j.
func (s EntrySlice) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}

// Punctuation contains all the characters that are not allowed as the last character in the title.
const Punctuation = ".!?"

// Valid returns an error if the entry is invalid in any way.
func (e Entry) Valid() error {
	if e.Type == "" {
		return errors.New("entry title does not have a prefix, example: Bugfix: restore old behavior")
	}

	if e.Title == "" {
		return errors.New("entry does not have a title")
	}

	if e.PrimaryID == 0 {
		return errors.New("primary issue ID not found")
	}

	lastChar := e.Title[len(e.Title)-1]
	if strings.ContainsAny(string(lastChar), Punctuation) {
		return fmt.Errorf("title ends with punctuation, e.g. a character out of %q", Punctuation)
	}

	if _, ok := EntryTypePriority[e.Type]; !ok {
		return fmt.Errorf("entry type %q is invalid, valid types: %v", e.Type, EntryTypePriority)
	}

	if len(e.Type)+len(e.Title)+1 > 80 {
		return errors.New("title is too long (max 80 characters)")
	}

	return nil
}

func readFile(filename string) (e Entry) {
	f, err := os.Open(filename)
	if err != nil {
		die("unable to open %v: %v", filename, err)
	}

	sc := bufio.NewScanner(f)
	if !sc.Scan() {
		die("unable to read first line from %v", filename)
	}

	title := sc.Text()
	data := strings.SplitN(title, ": ", 2)
	if len(data) == 2 {
		e.Type = strings.TrimSpace(capitalize(data[0]))
		e.TypeShort = EntryTypeAbbreviation[e.Type]
		data = data[1:]
	}
	e.Title = strings.TrimSpace(capitalize(data[0]))

	var text []string
	var sect string
	var verbatim bool // inside verbatim section
	for sc.Scan() {
		if sc.Err() != nil {
			die("unable to read lines from %v: %v", filename, sc.Err())
		}

		trimmedText := strings.TrimSpace(sc.Text())
		if !verbatim && strings.HasPrefix(trimmedText, "```") {
			// start new paragraph
			if sect != "" {
				text = append(text, sect)
			}
			sect = trimmedText
			verbatim = true
			continue
		}

		// ignore new lines inside verbatim section
		if !verbatim && trimmedText == "" {
			if sect != "" {
				text = append(text, sect)
			}

			sect = ""
			continue
		}

		if verbatim {
			if sect != "" {
				sect += "\n"
			}
			sect += sc.Text()
		} else {
			if sect != "" {
				sect += " "
			}
			sect += trimmedText
		}

		if verbatim && trimmedText == "```" {
			verbatim = false
		}
	}

	if verbatim {
		die("unmatched verbatim tag in %v", filename)
	}

	err = f.Close()
	if err != nil {
		die("error closing %v: %v", filename, err)
	}

	if sect != "" {
		text = append(text, sect)
	}

	if len(text) > 0 {
		links := text[len(text)-1]
		text = text[:len(text)-1]

		sc = bufio.NewScanner(strings.NewReader(links))
		sc.Split(bufio.ScanWords)
		for sc.Scan() {
			url, err := url.Parse(sc.Text())
			if err != nil {
				die("file %v: unable to parse url %q: %v", filename, sc.Text(), err)
			}
			e.URLs = append(e.URLs, url)
		}
	}

	for _, par := range text {
		e.Paragraphs = append(e.Paragraphs, capitalize(strings.TrimSpace(par)))
	}

	githubIDs(e.URLs, &e)

	err = e.Valid()
	if err != nil {
		die("file %v: %v", filename, err)
	}

	return e
}

var (
	issueRegexp       = regexp.MustCompile(`/.*/.*/issues/(\d+)`)
	pullRequestRegexp = regexp.MustCompile(`/.*/.*/pull/(\d+)`)
)

func safeParseInt(str string) int64 {
	val, err := strconv.ParseInt(str, 10, 64)
	if err != nil {
		die("unable to parse issue/PR ID %q: %v", str, err)
	}
	return val
}

// githubIDs extracts all issue and pull request IDs from the urls.
func githubIDs(urls []*url.URL, e *Entry) {
	for _, url := range urls {
		if url.Host != "github.com" {
			e.OtherURLs = append(e.OtherURLs, url)
			continue
		}

		switch {
		case issueRegexp.MatchString(url.Path):
			data := issueRegexp.FindStringSubmatch(url.Path)
			id := data[1]
			e.Issues = append(e.Issues, id)
			e.IssueURLs = append(e.IssueURLs, url)

			if e.PrimaryID == 0 {
				e.PrimaryID = safeParseInt(id)
				e.PrimaryURL = url
			}
		case pullRequestRegexp.MatchString(url.Path):
			data := pullRequestRegexp.FindStringSubmatch(url.Path)
			id := data[1]
			e.PRs = append(e.PRs, id)
			e.PRURLs = append(e.PRURLs, url)

			if e.PrimaryID == 0 {
				e.PrimaryID = safeParseInt(id)
				e.PrimaryURL = url
			}
		default:
			e.OtherURLs = append(e.OtherURLs, url)
		}
	}
}

func readEntries(versions []Release) (entries map[string][]Entry) {
	entries = make(map[string][]Entry)

	for _, ver := range versions {
		for _, file := range files(ver.path) {
			entries[ver.Version] = append(entries[ver.Version], readFile(file))
		}
	}

	// sort all entries according to priority, otherwise leave the original ordering
	for ver, list := range entries {
		sort.Stable(EntrySlice(list))
		entries[ver] = list
	}

	return entries
}

// wrapIndent formats the text in a column smaller than width characters,
// indenting each new line with indent spaces.
func wrapIndent(text string, width, indent int) (result string, err error) {
	if strings.HasPrefix(text, "```") {
		parts := strings.Split(text, "\n")
		sep := "\n" + strings.Repeat(" ", indent)
		return strings.Join(parts, sep), nil
	}

	sc := bufio.NewScanner(strings.NewReader(text))
	sc.Split(bufio.ScanWords)
	cl := 0
	for sc.Scan() {
		if sc.Err() != nil {
			return "", sc.Err()
		}

		spaceLen := 0
		if cl > 0 {
			// account for space between words, if there's already a word on the
			// current line
			spaceLen = 1
		}

		if cl+spaceLen+len(sc.Text()) > width {
			result += "\n"
			result += strings.Repeat(" ", indent)
			cl = 0
		}

		if cl > 0 {
			result += " "
			cl++
		}
		result += sc.Text()
		cl += len(sc.Text())
	}

	return result, nil
}

// capitalize returns a string with the first letter in upper case.
func capitalize(text string) string {
	if text == "" {
		return text
	}

	first, rest := text[0:1], text[1:]
	return strings.ToUpper(first) + rest
}

var helperFuncs = template.FuncMap{
	"wrapIndent": wrapIndent,
	"capitalize": capitalize,
}

func main() {
	buf, err := ioutil.ReadFile(opts.TemplateFile)
	if err != nil {
		die("unable to read template from %v: %v", opts.TemplateFile, err)
	}

	funcMap := sprig.GenericFuncMap()

	for i, m := range helperFuncs {
		funcMap[i] = m
	}

	templ, err := template.New("").Funcs(funcMap).Parse(string(buf))

	if err != nil {
		die("unable to compile template: %v", err)
	}

	type VersionChanges struct {
		Version string
		Date    string
		Entries []Entry
	}

	allReleases := readReleases(opts.InputDir)

	var changes []VersionChanges
	var releases []Release

	if len(opts.Versions) == 0 {
		releases = allReleases
	} else {
		for _, rel := range allReleases {
			for _, ver := range opts.Versions {
				if ver == rel.Version {
					releases = append(releases, rel)
				}
			}
		}
	}

	all := readEntries(releases)
	for _, ver := range releases {
		if len(all[ver.Version]) == 0 {
			continue
		}

		vc := VersionChanges{
			Version: ver.Version,
			Entries: all[ver.Version],
		}

		if ver.Date != nil {
			vc.Date = ver.Date.Format("2006-01-02")
		} else {
			vc.Date = "UNRELEASED"
		}

		changes = append(changes, vc)
	}

	wr := os.Stdout

	if opts.Output != "" {
		wr, err = os.Create(opts.Output)
		if err != nil {
			die("unable to create file %v: %v", opts.Output, err)
		}
	}

	err = templ.Execute(wr, changes)
	if err != nil {
		die("error executing template: %v", err)
	}

	if opts.Output != "" {
		err = wr.Close()
		if err != nil {
			die("error closing file %v: %v", opts.Output, err)
		}
	}
}
